var imgPostition=0;var myTimerInterval;var timeScrolling=4000;function unselectSelectorsImg(){let tabSelecteur=document.getElementsByClassName('selectorViewer');for(let i=0;i<tabSelecteur.length;i++){tabSelecteur[i].style.backgroundColor="white";}}function displayImg(imgNumber){let slider=document.getElementById('slider');let img=slider.firstChild.nextSibling;let sizeImg=img.width;let newPosition=imgNumber * sizeImg * -1;let strNewPosition=newPosition.toString()+"px";slider.style.left=strNewPosition;}function scrollImg(imgSelector){clearInterval(myTimerInterval);unselectSelectorsImg();imgSelector.style.backgroundColor="#54b454";imgPostition=imgSelector.getAttribute('name');displayImg(imgPostition);myTimerInterval=setInterval(myTimerScrollImg,timeScrolling);}function myTimerScrollImg(){let nbImg=document.getElementsByClassName('selectorViewer').length;imgPostition ++;if(imgPostition==nbImg){imgPostition=0;}unselectSelectorsImg();let imgSelector=document.getElementsByName(imgPostition)[0];imgSelector.style.backgroundColor="#54b454";displayImg(imgPostition);}function loadImg(path,targetContainer,onLoaded){const xhr=new XMLHttpRequest();xhr.onload=function(){const xml=xhr.responseXML;if(!xml){console.error("Le document XML est invalide.");return;}else{const containerSlider=document.createElement("div");containerSlider.id="containerSlider";const slider=document.createElement("div");slider.id="slider";targetContainer.appendChild(containerSlider);containerSlider.appendChild(slider);const scroll=document.createElement("div");scroll.id="scroll";targetContainer.appendChild(scroll);const images=xml.getElementsByTagName("image");for(let i=0;i < images.length;i++){const src=images[i].getElementsByTagName("src")[0].textContent;const altElement=images[i].getElementsByTagName("alt")[0];const img=document.createElement("img");img.src=src;img.alt=altElement ? altElement.textContent:"";slider.appendChild(img);const div=document.createElement("div");div.className="selectorViewer";div.setAttribute("name",i);if(i===0){div.style.backgroundColor="#54b454";}div.addEventListener("click",function(){scrollImg(this);});scroll.appendChild(div);}if(onLoaded){onLoaded();}}};xhr.onerror=function(){console.error("Erreur réseau lors du chargement du XML.");};xhr.open("GET",path,true);xhr.send();}
